'use client'; // Assure-toi que le fichier soit traité comme un composant client

import { useState, useEffect } from 'react';
import axios from 'axios';
import { IconButton } from '@mui/material';
import { Add as AddIcon, Edit as EditIcon, Delete as DeleteIcon } from '@mui/icons-material';
import Sidebar from "../../components/sidebar";  // Import Sidebar component
import Navbar from "../../components/Navbar";    // Import Navbar component

export default function Comptes() {
  // Initialiser l'état des utilisateurs, du chargement et des erreurs
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    // Effectuer une requête GET pour récupérer les utilisateurs
    axios
      .get("http://localhost:5000/api/login")
      .then((response) => {
        setUsers(response.data);  // Stocker les utilisateurs
        setLoading(false);         // Désactiver le chargement
      })
      .catch(() => {
        setError("Erreur de chargement des comptes.");  // En cas d'erreur
        setLoading(false);         // Désactiver le chargement
      });
  }, []);

  // Afficher un message de chargement ou d'erreur
  if (loading) return <p className="text-center text-gray-500">Chargement en cours...</p>;
  if (error) return <p className="text-center text-red-500">{error}</p>;

  // Fonction pour envoyer l'email
  const sendEmail = async (email, password) => {
    try {
      await axios.post("http://localhost:5000/api/send-email", {
        email,  // Email du destinataire
        subject: "Informations de Connexion à l'App",
        body: `Votre mot de passe est ${password}. Vous pouvez vous connecter en suivant ce lien: http://localhost:3000`,
      });
      alert("Email envoyé avec succès");
    } catch (error) {
      alert("Erreur lors de l'envoi de l'email");
    }
  };

  return (
    <div className="flex h-screen min-h-screen w-screen">
      {/* Sidebar and Navbar layout */}
      <Sidebar className="h-screen hidden lg:block" /> {/* Sidebar hidden on small screens */}
      <div className="w-full flex flex-col h-screen">
        <Navbar />
        <div className="w-full flex-1 py-5 px-6 overflow-hidden">
          <h1 className="text-3xl font-semibold mb-6 text-center text-gray-800">Liste des comptes</h1>

          {/* Tableau des étudiants avec overflow */}
          <div className="overflow-x-auto overflow-y-auto max-h-[800px]">
            <table className="min-w-full bg-white border border-gray-300 rounded-lg shadow-md">
            <thead className="bg-blue-700 text-white">
            <tr>
                  <th className="py-3 px-6 text-left">ID</th>
                  <th className="py-3 px-6 text-left">Email</th>
                  <th className="py-3 px-6 text-left">Mot de Passe</th>
                  <th className="py-3 px-6 text-left">Rôle</th>
                  <th className="py-3 px-6 text-left">Envoyer Email</th>
                </tr>
              </thead>
              <tbody>
                {users.length > 0 ? (
                  users.map((user, index) => (
                    <tr
                      key={user.id}
                      className={`${index % 2 === 0 ? 'bg-blue-100' : 'bg-white'} hover:bg-gray-100 transition duration-200`}
                    >
                      <td className="py-3 px-6">{user.id}</td>
                      <td className="py-3 px-6">{user.email}</td>
                      <td className="py-3 px-6">{user.password}</td>
                      <td className="py-3 px-6">{user.role}</td>
                      <td className="py-3 px-6 text-center">
                        <button
                          onClick={() => sendEmail(user.email, user.password)}
                          className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 transition duration-300"
                        >
                          Envoyer Email
                        </button>
                      </td>
                    </tr>
                  ))
                ) : (
                  <tr>
                    <td colSpan={5} className="py-3 px-6 text-center text-gray-500">
                      Aucun compte trouvé.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
