"use client";  // Assurez-vous d'ajouter cette ligne au début de votre fichier

import { useState } from 'react';
import { FaProjectDiagram, FaClipboardList, FaCheckCircle, FaTachometerAlt, FaSignOutAlt, FaBars } from 'react-icons/fa';
import Link from 'next/link';  // Assurez-vous d'importer Link de Next.js

const Sidebar = () => {
  const [isGestionOpen, setGestionOpen] = useState(false);
  const [isAffectationOpen, setAffectationOpen] = useState(false);
  const [isCreationCompteOpen, setCreationCompteOpen] = useState(false);
  const [isIMPORTATIONOpen, setIMPORTATIONOpen] = useState(false);
  const [isGenererOpen, setGenererOpen] = useState(false);
  const [isSidebarOpen, setSidebarOpen] = useState(true); // Contrôle de la visibilité de la sidebar

  const toggleGestion = () => setGestionOpen(!isGestionOpen);
  const toggleAffectation = () => setAffectationOpen(!isAffectationOpen);
  const toggleCreationCompte = () => setCreationCompteOpen(!isCreationCompteOpen);
  const toggleIMPORTATION = () => setIMPORTATIONOpen(!isIMPORTATIONOpen);
  const toggleGenerer = () => setGenererOpen(!isGenererOpen);
  const toggleSidebar = () => setSidebarOpen(!isSidebarOpen);  // Toggle pour mobile

  return (
<div className={`h-screen ${isSidebarOpen ? 'w-64' : 'w-16'} bg-blue-500 text-white p-4 transition-all duration-500 shadow-lg`}>
<div className="flex items-center justify-between mb-5">
        <h1 className={`text-lg font-bold ${isSidebarOpen ? 'text-center md:text-left' : 'text-center'}`}></h1>
        <button
          className="md:hidden text-2xl focus:outline-none"
          onClick={toggleSidebar}
          aria-label="Toggle Sidebar"
        >
          <FaBars />
        </button>
      </div>

      <ul className="space-y-2">
        <Link href="/dashboard">
          <li className={`flex items-center gap-3 p-3 hover:bg-blue-400 cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
            <FaTachometerAlt /> {isSidebarOpen && 'Dashboard'}
          </li>
        </Link>

        <li
          className={`flex items-center gap-3 p-3 hover:bg-blue-400 cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
          onClick={toggleAffectation}
        >
          <FaClipboardList /> {isSidebarOpen && 'Affectation'}
        </li>

        {isAffectationOpen && (
          <ul className="ml-5 space-y-2">
            <li
              className={`p-3 hover:bg-blue-400 cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
              onClick={toggleIMPORTATION}
            >
              {isSidebarOpen && 'IMPORTATION'}
            </li>

            {isIMPORTATIONOpen && (
              <ul className="ml-5 space-y-2">
                <Link href="/users/readEtu">
                  <li className="flex items-center gap-3 p-3 hover:bg-blue-400 cursor-pointer transition-all duration-300">
                    <FaProjectDiagram /> {isSidebarOpen && 'Gestion Étudiants'}
                  </li>
                </Link>
                <Link href="/users/readEnca">
                  <li className="flex items-center gap-3 p-3 hover:bg-blue-400 cursor-pointer transition-all duration-300">
                    <FaProjectDiagram /> {isSidebarOpen && 'Gestion Encadrants'}
                  </li>
                </Link>
                <Link href="/users/readTute">
                  <li className="flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300">
                    <FaProjectDiagram /> {isSidebarOpen && 'Gestion Tuteur'}
                  </li>
                </Link>
                <Link href="/users/readSuj">
                  <li className="flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300">
                    <FaProjectDiagram /> {isSidebarOpen && 'Gestion Sujet'}
                  </li>
                </Link>
              </ul>
            )}

            <li
              className={`p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
              onClick={toggleGenerer}
            >
              {isSidebarOpen && 'Générer'}
            </li>

            {isGenererOpen && (
              <ul className="ml-5 space-y-2">
                 <Link href="/users/readgenerer">
                <li className="flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300">
                  <FaProjectDiagram /> {isSidebarOpen && 'gestion de groupe'}
                </li>
                </Link>
                <li className="flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300">
                  <FaProjectDiagram /> {isSidebarOpen && 'affecter tuteur'}
                </li>
                <li className="flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300">
                  <FaProjectDiagram /> {isSidebarOpen && 'affecter sujet'}
                </li>
              </ul>
            )}

            <li
              className={`p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}
              onClick={toggleCreationCompte}
            >
              {isSidebarOpen && 'Création des Comptes'}
            </li>

            {isCreationCompteOpen && (
              <ul className="ml-5 space-y-2">
                <Link href="/users/compte">
                  <li className="flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300">
                    <FaProjectDiagram /> {isSidebarOpen && 'Créer Compte'}
                  </li>
                </Link>
              </ul>
            )}
          </ul>
        )}

        <li className={`flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
          <FaCheckCircle /> {isSidebarOpen && 'Suivi'}
        </li>
        <li className={`flex items-center gap-3 p-3 hover:bg-blue-400 cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
          <FaCheckCircle /> {isSidebarOpen && 'Soutenance'}
        </li>

        <Link href={`/`}>
          <li className={`flex items-center gap-3 p-3 hover:bg-blue-400  cursor-pointer transition-all duration-300 ${!isSidebarOpen ? 'justify-center' : ''}`}>
            <FaSignOutAlt /> {isSidebarOpen && 'Déconnexion'}
          </li>
        </Link>
      </ul>
    </div>
  );
};

export default Sidebar;
